class Solution:
    def maxDistance(self, s: str, k: int) -> int:
        n = s_cnt = e = w = 0
        ans = 0
        for i, c in enumerate(s):
            if c == 'N':
                n += 1
            elif c == 'S':
                s_cnt += 1
            elif c == 'E':
                e += 1
            else:
                w += 1
            L = i + 1
            d = abs(n - s_cnt) + abs(e - w) + 2 * k
            ans = max(ans, min(L, d))
        return ans
